def get_field_value(self, field):
    lang = get_language()
    if hasattr(self, f"{field}_{lang}"):
        return getattr(self, f"{field}_{lang}")
    elif hasattr(self, f"{field}_{lang[:2]}"):
        return getattr(self, f"{field}_{lang[:2]}")
    else:
        default_lang = fallback_language()
        if hasattr(self, f"{field}_{default_lang}"):
            return getattr(self, f"{field}_{default_lang}")
        else:
            return getattr(self, f"{field}_{settings.LANGUAGE_CODE}")

def handle_response(self, payload):
    if self.state == SASLState.SUCCESS_SIMULATE_CHALLENGE:
        if payload != b"":
            self.state = SASLState.FAILURE
            raise SASLFailure(None, "protocol violation")
        self.state = SASLState.SUCCESS
        return SASLState.SUCCESS, None
    if self.state != SASLState.CHALLENGE:
        raise RuntimeError("no challenge made")
    try:
        next_state, payload = yield from self.interface.respond(payload)
    except SASLFailure:
        self.state = SASLState.FAILURE
        raise
    next_state = SASLState.from_reply(next_state)
    if next_state == SASLState.SUCCESS and payload is not None:
        self.state = SASLState.SUCCESS_SIMULATE_CHALLENGE
        return SASLState.CHALLENGE, payload
    self.state = next_state
    return next_state, payload

def record_view(pid_value=None, resolver=None, template=None, permission_factory=None, view_method=None, **kwargs):
    try:
        pid, record = resolver.resolve(pid_value)
    except PIDDoesNotExistError:
        abort(404)
    except PIDUnregistered:
        abort(404)
    except PIDMissingObjectError as e:
        current_app.logger.exception(f"No object assigned to {e.pid}.", extra={'pid': e.pid})
        abort(500)
    except PIDRedirectedError as e:
        try:
            return redirect(url_for(f".{e.destination_pid.pid_type}", pid_value=e.destination_pid.pid_value))
        except BuildError:
            current_app.logger.exception(f"Invalid redirect - pid_type '{e.destination_pid.pid_type}' endpoint missing.", extra={'pid': e.pid, 'destination_pid': e.destination_pid})
            abort(500)
    permission_factory = permission_factory or current_permission_factory
    if permission_factory and not permission_factory(record).can():
        from flask_login import current_user
        if not current_user.is_authenticated:
            return redirect(url_for(current_app.config['RECORDS_UI_LOGIN_ENDPOINT'], next=request.url))
        abort(403)
    return view_method(pid, record, template=template, **kwargs)
